"""New explicitly authorized Stage1A-2 coverage, no retry of old cells."""
import json
import sys
import time
import urllib.request
from pathlib import Path
from experiments.json_action_v2 import coverage
from router.model_registry import ModelRegistry

BASE=coverage.ROOT/'evidence/json-action-adapter-v2/stage-1a-2'
TASKS=[('B','search_code','query','Use search_code to find the exact source content VALUE=17 in the existing app/value.py file. Return one search_code action with a nonempty literal query that finds that source content. Preserve every file.'),
       ('C','delete_file','path','Delete only delete-coverage.txt, the experiment-owned disposable file already read below. Preserve every other file. Return one delete_file action.'),
       ('D','run_command','command','Run the existing README documented entrypoint python -m app.runner using run_command in Docker. Expected documented output is 17. Preserve every file. Return one run_command action.')]
def register():
    BASE.mkdir(exist_ok=False)
    previous=coverage.ROOT/'evidence/json-action-adapter-v2/stage-1a'
    oldstage=coverage.ROOT/'evidence/json-action-adapter-v2/stage-1'
    hashes={str(p.relative_to(coverage.ROOT)):coverage.sha(p) for directory in (previous,oldstage) for p in directory.rglob('*') if p.is_file()}
    fixture=json.loads((previous/'registered-fixture.json').read_text())
    fixture['disposable_addition']={'delete-coverage.txt':'STAGE1A DISPOSABLE\n'}
    coverage.save(BASE/'registered-fixture.json',fixture)
    coverage.save(BASE/'coverage-tasks.json',TASKS)
    target={'path':'app/value.py','line':1,'text':'VALUE=17'}
    coverage.save(BASE/'validation-contract.json',{'search_required_match':target,'delete_precondition':'delete-coverage.txt exists with registered bytes','delete_postcondition':'draft excludes only delete-coverage.txt; Docker snapshot confirms absence and unrelated hashes unchanged','command':'python -m app.runner','stdout':'17\n','exit_code':0,'independent_negative_controls':True,'source_oracle':coverage.ORACLE,'actual_oracle_addition':"if kind=='B': assert expected['required_match'] in observation['matches']"})
    prereg='''# Stage1A-2 preregistration
New separately authorized coverage; previous search VALUE = remains FAILED. Three cells in frozen coverage-tasks.json, ordered B search/C delete/D command, one native completion each, no retries or normalization. Freeze fixture/validation-contract hashes before completion. Reuse immutable copied rp07 fixture, known target app/value.py line1 VALUE=17; new search request may name target but harness cannot manufacture/replace model action. Disposable deletion identity delete-coverage.txt only. Command existing documented python -m app.runner, stdout17 newline, exit0. All tool arguments genuinely generated by existing Qwen worker. No list_dir rerun.
Unchanged native snapshot SYSTEM/ToolRegistry/PermissionPolicy/ToolExecutor/ValidationEngine; all ten tools exposed. Qwen3.5-4B Q4_K_M b11132, context16384, q8_0/q8_0, temp0, enable_thinkingfalse, max_tokens4096, required tool choice, parallelfalse, no seed, no schema protocol. One heavy worker; no evaluator/conflicting request before calls. Existing pinned Docker/security/verifier unchanged; fresh18/18required. Fixture setup/prerequisite harness read not model evidence. No global prompts changed.
Existing file metadata tools operate on experimental virtual draft through existing registry/permissions; independent pinned Docker verifies output. Deletion is native overlay draft deletion, never canonical publication; Docker before snapshot proves disposable existed, after snapshot proves absent and unrelated files unchanged. No pretending native metadata itself is a Docker process. Harness read_file only supplies required prior read of disposable. Commands run through existing Docker ValidationEngine only. All fixtures created in isolated evidence workspace, no user/production modifications.
Qualifies only genuine nonempty target action, real executor result, independent Docker oracle PASS and negative control FAIL, preserved raw action and unchanged canonical workspace. New search oracle must contain exact frozen expected match, not merely match an arbitrary substring elsewhere. On any nonqualifying cell stop, preserve failure, no instruction/query edits or retries; report a separate proposed scientifically justified attempt only if needed. No arbitrary bounds. Maximum qualifying value from all approved evidence + fixed256margin. Failed old query excluded, successful old app listing length3 retained. No bounded schema/converter/tokenizer/T10/Stage2 in this stage. Stop after report, wait approval.
'''
    (BASE/'PREREGISTRATION.md').write_text(prereg,encoding='utf-8')
    (BASE/'AMENDMENT.md').write_text('''# Stage1A-2 amendment
Original run stopped on failed literal search, leaving search_code.query/delete_file.path/run_command.command without qualifying observations. This new approved run solely obtains legitimate coverage. New search task specifies known source target; model must emit query. New disposable identity delete-coverage.txt authorized by user. No alteration/retry of old failure. Fixed margin256. No changes to model/artifact/quantization/runtime/context/KV/max_tokens/temperature/thinking/global prompts/Docker policy/registry/permissions/native validator/production/frozen benchmark. Qualified action requires independent execution validation, not fixture metadata or Registry.check alone.
''',encoding='utf-8')
    inventory={'previous_stage1_sha256':hashes,'preregistration_sha256':coverage.sha(BASE/'PREREGISTRATION.md'),'amendment_sha256':coverage.sha(BASE/'AMENDMENT.md'),'tasks_sha256':coverage.sha(BASE/'coverage-tasks.json'),'fixture_sha256':coverage.sha(BASE/'registered-fixture.json'),'validation_sha256':coverage.sha(BASE/'validation-contract.json')}
    coverage.save(BASE/'manifest.json',inventory)
    # Compatibility with existing coverage runner; exact amendment bytes copied.
    (BASE/'AMENDMENT-TO-BOUND-POLICY.md').write_bytes((BASE/'AMENDMENT.md').read_bytes())
    coverage.save(BASE/'evidence-inventory.json',inventory)
    print('Stage1A-2 tasks, fixture, preregistration and amendment frozen',flush=True)

def execute():
    r=ModelRegistry(); assert r.verified_residency()=='Qwen/Qwen3.5-4B' and r._owns_server()
    manifest=json.loads((coverage.ROOT/'evidence/json-action-adapter-v2/manifest.json').read_text())
    before={p:coverage.sha(coverage.ROOT/p) for p in manifest['frozen_sha256']}
    coverage.save(BASE/'before-source-sha256.json',before)
    coverage.BASE=BASE; coverage.TASKS=TASKS
    coverage.execute(delete_target='delete-coverage.txt',required_search_match={'path':'app/value.py','line':1,'text':'VALUE=17'})
    inventory=json.loads((BASE/'manifest.json').read_text())
    coverage.save(BASE/'integrity-after.json',{'source_changes':[p for p,d in before.items() if coverage.sha(coverage.ROOT/p)!=d],'prior_evidence_changes':[p for p,d in inventory['previous_stage1_sha256'].items() if coverage.sha(coverage.ROOT/p)!=d]})

if __name__=='__main__':
    if sys.argv[1]=='register': register()
    elif sys.argv[1]=='execute': execute()
